using UnityEngine;

namespace Astrea.BattleActions;

[CreateAssetMenu(fileName = "WickedChantingAction", menuName = "Data/Battle/Battle Actions/Sothis/WickedChanting Action")]
public class WickedChantingAction : ChantingAction
{
	public override void CastTargetAmount(GameObject target, int amount, GameObject source)
	{
		CastTarget(target, source);
		int num = target.GetComponent<UnitEffects>().IsAfflictionActiveGetAmount();
		if (num > 0)
		{
			AddChantingToPlayer(source, num * amount);
		}
	}
}
